from decimal import Decimal, Context, ROUND_HALF_UP, InvalidOperation

_INT4_MIN = -2147483648
_INT4_MAX = 2147483647
_NUMERIC_MAX_RESULT_SCALE = 2000


def _to_int4(value):
    # PL/pgSQL assignment numeric -> int: rounds half away from zero, errors on overflow/NaN
    if value is None:
        return None
    d = Decimal(value)
    if d.is_nan() or d.is_infinite():
        raise ValueError("cannot convert NaN/Infinity to integer")
    ctx = Context(prec=max(28, len(d.as_tuple().digits) + 10), rounding=ROUND_HALF_UP,
                  Emax=999999999, Emin=-999999999)
    i = int(d.to_integral_value(rounding=ROUND_HALF_UP, context=ctx))
    if i < _INT4_MIN or i > _INT4_MAX:
        raise OverflowError("integer out of range")
    return i


def _pg_round(amount, n):
    if amount is None or n is None:
        return None
    if amount.is_nan():
        return Decimal("NaN")
    if amount.is_infinite():
        return amount
    if n > _NUMERIC_MAX_RESULT_SCALE:
        n = _NUMERIC_MAX_RESULT_SCALE
    if n < -_NUMERIC_MAX_RESULT_SCALE:
        n = -_NUMERIC_MAX_RESULT_SCALE
    digits = len(amount.as_tuple().digits)
    adj = amount.adjusted()
    prec = max(28, abs(adj) + digits + abs(n) + 20)
    ctx = Context(prec=prec, rounding=ROUND_HALF_UP, Emax=999999999, Emin=-999999999)
    q = Decimal(1).scaleb(-n, context=ctx)
    result = amount.quantize(q, rounding=ROUND_HALF_UP, context=ctx)
    if n < 0:
        result = result.quantize(Decimal(1), rounding=ROUND_HALF_UP, context=ctx)
    if result.is_zero() and result.is_signed():
        result = result.copy_abs()
    return result


def currencyround(p_amount, p_curto_id, p_costing, *, data):
    if p_amount is None or p_curto_id is None:
        return p_amount

    rows = data.select("c_currency", c_currency_id=p_curto_id)
    rows = [r for r in rows
            if r.get("c_currency_id") is not None
            and Decimal(r["c_currency_id"]) == Decimal(p_curto_id)]

    std_vals = [r["stdprecision"] for r in rows if r.get("stdprecision") is not None]
    cost_vals = [r["costingprecision"] for r in rows if r.get("costingprecision") is not None]
    max_std = max(std_vals) if std_vals else None
    max_cost = max(cost_vals) if cost_vals else None

    v_std = _to_int4(max_std)
    v_cost = _to_int4(max_cost)

    if v_std is None:
        return p_amount

    if p_costing is not None and p_costing == "Y":
        if v_cost is None:
            return None
        return _pg_round(p_amount, v_cost)

    return _pg_round(p_amount, v_std)

